const curriculaOfClasses = `-- name: CurriculaOfClasses :many
SELECT DISTINCT class_id, curriculum_id FROM syllabus.assignments WHERE class_id = ANY ($1::uuid[])
`

type CurriculaOfClassesRow struct {
	ClassID      *uuid.UUID
	CurriculumID uuid.UUID
}

// Giáo trình các lượt chặng của lớp (gắn chặng cho đợt Big Test).
func (q *Queries) CurriculaOfClasses(ctx context.Context, classIds []uuid.UUID) ([]CurriculaOfClassesRow, error) {
	rows, err := q.db.Query(ctx, curriculaOfClasses, classIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []CurriculaOfClassesRow
	for rows.Next() {
		var i CurriculaOfClassesRow
		if err := rows.Scan(&i.ClassID, &i.CurriculumID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

